$ErrorActionPreference='Stop';$r='D:\R35T1\collateral2';if(Test-Path $r){throw'R35 collateral2 output exists'};New-Item "$r\jobs" -ItemType Directory|Out-Null;$s=Get-Content 'D:\R34C953R2\SUMMARY.json' -Raw|ConvertFrom-Json;$m=@($s.failures|?{$_.state-eq'HOLD_BACK_NOTCH_MULTIPLE_BF_DF_MATCHES'});$rows=@();$n=0;$u=New-Object Text.UTF8Encoding($false);foreach($x in $m){$old=Get-Content (Join-Path $x.diagnosticRoot 'RESULT.json') -Raw|ConvertFrom-Json;$q=@($old.pairedCandidates);$d=[math]::Abs([double]$q[0].meanAngleDegrees-[double]$q[1].meanAngleDegrees);$d=[math]::Min($d,360-$d);if($d-le60){continue};$n++;$j=Get-Content (Join-Path (Split-Path $x.diagnosticRoot) 'back_job.json') -Raw|ConvertFrom-Json;$b=(Get-FileHash $j.bf).Hash;$f=(Get-FileHash $j.df).Hash;$j.output="$r\C$n";$jp="$r\jobs\C$n.json";[IO.File]::WriteAllText($jp,($j|ConvertTo-Json -Depth 8),$u);if([IO.File]::ReadAllBytes($jp)[0]-ne123){throw'Job encoding failed'};& 'D:\AFCV1\rt\python.exe' -B 'D:\R35T1RT\R35.py' --job $jp;if($LASTEXITCODE){throw "R35 C$n exit $LASTEXITCODE"};$z=Get-Content "$r\C$n\RESULT.json" -Raw|ConvertFrom-Json;$g=$z.bf.multiPairExteriorCleanResolution;$ok=($z.pairedCandidateCount-eq1-and$g.state-eq'PASS_UNIQUE_BOTH_CHANNELS_EXTERIOR_CLEAR_PAIR'-and$g.distantExteriorDirtyCandidatesRejected-eq$true-and(Get-FileHash $j.bf).Hash-eq$b-and(Get-FileHash $j.df).Hash-eq$f);$rows+=[ordered]@{identity=$x.identity;angle=$z.pairedCandidates[0].meanAngleDegrees;passed=$ok};if(-not$ok){throw "R35 C$n invariant failed"}};if($n-ne8){throw "R35 collateral count $n"};[ordered]@{state='PASS_R35_COLLATERAL_8_OF_8';caseCount=$n;rows=$rows;sourceMutationPerformed=$false}|ConvertTo-Json -Depth 4 -Compress
